package dominoes

// Domino represents a single domino stone with two halves.
type Domino [2]int

// MakeChain tries to order the given dominoes into a closed chain in which
// adjacent halves match and the two unpaired halves (first and last) match
// each other. It returns the chain and true if one exists, otherwise nil
// and false.
func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)
	switch {
	case n == 0:
		return []Domino{}, true
	case n == 1:
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	// A closed chain exists only if every value appears an even number of
	// times and all dominoes form a single connected component.
	degree := make(map[int]int, 2*n)
	adj := make(map[int][]int, n)
	for i, d := range input {
		degree[d[0]]++
		degree[d[1]]++
		adj[d[0]] = append(adj[d[0]], i)
		adj[d[1]] = append(adj[d[1]], i)
	}
	for _, deg := range degree {
		if deg%2 != 0 {
			return nil, false
		}
	}

	// Connectivity check over the values that appear in some domino.
	start := -1
	for v := range degree {
		if start == -1 {
			start = v
		}
	}
	seen := make(map[int]bool, len(degree))
	seen[start] = true
	queue := []int{start}
	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		for _, e := range adj[v] {
			u := input[e][0] ^ input[e][1] ^ v
			if !seen[u] {
				seen[u] = true
				queue = append(queue, u)
			}
		}
	}
	if len(seen) != len(degree) {
		return nil, false
	}

	// Hierholzer's algorithm: walk the graph, using each domino exactly once.
	type frame struct {
		vertex int
		edge   int // index of the domino used to enter vertex, -1 for the start
	}
	used := make([]bool, n)
	stack := []frame{{start, -1}}
	circuitEdges := make([]int, 0, n)
	for len(stack) > 0 {
		top := &stack[len(stack)-1]
		edge := -1
		var next int
		for _, e := range adj[top.vertex] {
			if !used[e] {
				used[e] = true
				edge = e
				next = input[e][0] ^ input[e][1] ^ top.vertex
				break
			}
		}
		if edge != -1 {
			stack = append(stack, frame{next, edge})
		} else {
			if top.edge != -1 {
				circuitEdges = append(circuitEdges, top.edge)
			}
			stack = stack[:len(stack)-1]
		}
	}

	// circuitEdges holds the Eulerian circuit in reverse order; reverse it.
	for i, j := 0, len(circuitEdges)-1; i < j; i, j = i+1, j-1 {
		circuitEdges[i], circuitEdges[j] = circuitEdges[j], circuitEdges[i]
	}

	// Orient each domino so that consecutive halves match.
	chain := make([]Domino, n)
	var cur int
	for i, e := range circuitEdges {
		d := input[e]
		if i == 0 || d[0] == cur {
			chain[i] = d
			cur = d[1]
		} else {
			chain[i] = Domino{d[1], d[0]}
			cur = d[0]
		}
	}
	return chain, true
}

